// ============ 平方阶的增长有多快 ============
//
//   n = 10    →  加 100 次
//   n = 100   →  加 10000 次      （n 变大 10 倍，次数变大 100 倍！）
//   n = 1000  →  加 1000000 次
//
// 对比一下线性阶：同样是 n 从 10 涨到 1000，
// 线性阶的代价涨了 100 倍，平方阶的代价涨了 10000 倍。
// 这就是为什么 O(n²) 的算法在数据量大时会突然"跑不动"。
//
// ============ 嵌套循环怎么数 ============
//
//   外层 i = 0 :   内层跑 n 次
//   外层 i = 1 :   内层跑 n 次
//   ...
//   外层 i = n-1:  内层跑 n 次
//   ────────────────────────────
//   一共 n × n = n² 次
//
// 记住一条：**嵌套循环相乘，并列循环相加**。

// 计数器
long countQuadratic(int n)
{
// 计数器
    long cnt = 0;
// 两个循环变量
    int i, j;

// 外层跑 n 次
    for (i = 0; i < n; i++)
    {
// 内层也跑 n 次 —— 两层相乘就是 n²
        for (j = 0; j < n; j++)
        {
// 关键操作：每进一次内层就加一次
            cnt++;
        }
    }

// 返回总次数，答案应该正好是 n²
    return cnt;
}

